function packForm(formSel, data = {})
{
  $(formSel).serializeArray().map(function(x){
    data[x.name] = x.value;
  });

  return data;
}

function populateForm(formSelector, data) {
  $.each(data, function(key, value){
    $('[name='+key+']', formSelector).val(value);
  });
}

function brDatetoUsa(datestring)
{
  var dateSplitted = datestring.split('/');
  return dateSplitted[2] + '-' + dateSplitted[1] + '-' + dateSplitted[0];
}

function usaDatetoBr(datestring)
{
  var dateSplitted = datestring.split('-');
  return dateSplitted[2] + '/' + dateSplitted[1] + '/' + dateSplitted[0];
}

function dataAtualFormatada(dt){
  var data = new Date(dt),
      dia  = data.getDate().toString(),
      diaF = (dia.length == 1) ? '0'+dia : dia,
      mes  = (data.getMonth()+1).toString(), //+1 pois no getMonth Janeiro começa com zero.
      mesF = (mes.length == 1) ? '0'+mes : mes,
      anoF = data.getFullYear();
  return diaF+"/"+mesF+"/"+anoF;
}

function formattedCurrentDate() {
  const now = new Date();
  return now.getDate().toString().padStart(2, '0')
    + (now.getMonth() + 1).toString().padStart(2, '0')
    + now.getFullYear().toString();
}

function reloadTable(tableId) {
  $("#" + tableId).DataTable().ajax.reload();
}

function convertBrCoinToFloat(valor){

  if(valor === ""){
    valor =  0;
  }else{
    valor = valor.replace(".","");
    valor = valor.replace(",",".");
    valor = parseFloat(valor);
  }
  return valor;

}

function formatFloatToBrCoin(value) {
  let formatter = new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  });

  return formatter.format(value).replace('R$', '').trim();
}

//formatar valor real brasileiro
//funcao similar ao formatFloatToBrCoin
function convertToReal(number, options = {}) {
  const { moneySign = true } = options;

  if(Number.isNaN(number) || !number) return "need a number as the first parameter";

  if(typeof number === "string") { // n1
      number = Number(number);
  }

  let res;

  const config = moneySign ? {style: 'currency', currency: 'BRL'} : {minimumFractionDigits: 2};

  moneySign
  ? res = number.toLocaleString('pt-BR', config)
  : res = number.toLocaleString('pt-BR', config)

  const needComma = number => number <= 1000;
  if(needComma(number)) {
      res = res.toString().replace(".", ",");
  }

  return res; // n2
}

class Crud {
    constructor(resourceName, singularName, pluralName, dataTableColumns) {
        this.singularName = singularName;
        this.resourceModel = new ResourceModel(resourceName);
        this.formSel = '#form-' + resourceName;
        this.$resourceModal = $('#modal-' + resourceName);
        this.$createBtn = $('#create-' + resourceName + '-btn');
        this.$submitBtn = $('#form-save-' + resourceName + '-btn');
        this.$resourceId = $('#' + resourceName + '-id');
        this.$form = $(this.formSel);
        this.$advancedSearchForm = $('#advanced-search-' + resourceName);
        this.resourceTable = new SearaTable(
            'table-' + resourceName,
            resourceName + '/dataTable',
            dataTableColumns,
            singularName,
            pluralName,
            () => packForm('#advanced-search-' + resourceName)
        );
    }

    initialize() {
        this.resourceTable.loadTable();
        this.$createBtn.on('click', () => {
            this._showForm();
        });

        this.$submitBtn.on('click', () => {
            let id = this.$resourceId.val();

            if (!this.$form.parsley().validate()) {
                return;
            }

            if ('' === id) {
                this._storeResource();
                return;
            }

            this._updateAccount(id);
        });

        const thisCrud = this;
        this.$resourceModal.on('shown.bs.modal', function () {
            thisCrud.$form.find('input:first:visible').focus();
        });

        this.$advancedSearchForm.on('change', () => {
            thisCrud.resourceTable.reloadTable();
        });
    }

    editResource(id) {
        SearaLoader.showModal("Carregando dados...");
        const thisCrud = this;
        this.resourceModel.read(id, function (data) {
            thisCrud._showForm();
            populateForm(thisCrud.formSel, data);
            reloadAllMasks();
            thisCrud.$resourceId.val(id);
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }

    destroyResource(id, confirmationText) {
        const thisCrud = this;
        swal({
            title: 'Atenção',
            text: confirmationText,
            type: 'warning',
            showCancelButton: true
        }).then(function() {
            SearaLoader.showModal('Aguarde ...');
            thisCrud.resourceModel.delete(id, function (response) {
                notify.response(response);
                thisCrud.resourceTable.reloadTable();
            }).fail(function (jqXHR) {
                notify.response(jqXHR.responseJSON);
            }).always(function(){
                SearaLoader.hideModal();
            });
        });
    }

    _showForm() {
        this.$resourceId.val('');
        this.$form.trigger('reset');
        this.$form.parsley().reset();
        this.$resourceModal.modal('show');
    }

    _closeForm() {
        this.$resourceModal.modal('hide');
    }

    _storeResource() {
        let formData = packForm(this.formSel);
        SearaLoader.showModal('Cadastrando ' + this.singularName + ' ...');

        const thisCrud = this;
        this.resourceModel.create(formData, function (response) {
            notify.response(response);
            thisCrud._closeForm();
            thisCrud.resourceTable.reloadTable();
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }

    _updateAccount(id) {
        let formData = packForm(this.formSel);
        SearaLoader.showModal('Atualizando ' + this.singularName + ' ...');

        const thisCrud = this;
        this.resourceModel.update(id, formData, function (response) {
            notify.response(response);
            thisCrud._closeForm();
            thisCrud.resourceTable.reloadTable();
        }).fail(function (jqXHR) {
            notify.response(jqXHR.responseJSON);
        }).always(function () {
            SearaLoader.hideModal();
        });
    }
}

let PaymentModule = (function () {
    const columns = [
        {data: 'company_manager', name: 'company_manager'},
        {data: 'customer', name: 'customer'},
        {data: 'payment_date', name: 'payment_date'},
        {data: 'created_at', name: 'created_at'},
        {data: 'amount', name: 'amount', className: 'formatted_number'},
        {data: 'action', name: 'action', orderable: false, searchable: false}
    ];
    const crud = new Crud(
        'payment',
        'pagamento',
        'pagamentos',
        columns
    );

    function index() {
        crud.initialize();
    }

    function deletePayment(id) {
        crud.destroyResource(id, 'Deseja excluir esse pagamento?')
    }

    function editPayment(id) {
        crud.editResource(id);
    }

    return {
        index: index,
        deletePayment: deletePayment,
        editPayment: editPayment
    };
})();

$(() => {
    PaymentModule.index();
});

function deletePayment(id) {
    PaymentModule.deletePayment(id);
}

function editPayment(id) {
    PaymentModule.editPayment(id);
}

